\title{The Quadratic-Residue Footprint Dial:\\
Exact Arithmetic of a Sieve-Yield Feature,\\
and a Provable Zero-Information Barrier}
\author{Aristotle}
\date{22 August 2026}

\begin{document}
\maketitle

\begin{abstract}
The quadratic sieve factors the values $v(x)=x^2-N$ over a fixed factor base of small
primes. A per-modulus \emph{yield dial} --- a cheap predictor of how many fully-factored
relations a given $N$ will produce --- is a standard practical tool, and empirically its
residual is not noise: adding the theoretically motivated feature
$W(N)=\sum 2/p$, summed over factor-base primes $p$ modulo which $N$ is a quadratic
residue, raises the out-of-sample coefficient of determination from $0.3927$ to $0.5691$
in one regime and from $0.2063$ to $0.3078$ in a harder one.

This paper supplies the exact mathematics behind that observation, and the exact limits of
what such a feature can do. We prove: (i) a \emph{mean-footprint identity} showing that
$W(N)$ is not a heuristic approximation but exactly the average number of factor-base
primes dividing a sieve value over a full period; (ii) a \emph{Hensel-lifting theorem}
extending the identity verbatim to prime powers, with a complementary $\bmod\ 8$ vanishing
at the even prime; (iii) the \emph{exact law} of the dial over a period of moduli --- the
quadratic-residue indicators at distinct primes are exactly independent with $(p+1)/2$
favourable residues out of $p$ --- whence the mean $\sum(p+1)/p^{2}$ and the closed-form
\emph{variance} $\sum(p^{2}-1)/p^{4}$, the latter strictly positive but uniformly bounded
by $1/2$; (iv) the \emph{exact information capacity}: the dial's range has precisely
$2^{|\base|}$ elements, so it carries exactly $|\base|$ bits; (v) an exact finite-sample
\emph{least-squares lift theory}, giving
$\Delta R^{2}=\langle r,v\rangle^{2}/(\|v\|^{2}\TSS)=\rho^{2}(1-R^{2}_{\text{before}})$
with the ceiling $\Delta R^{2}\le 1-R^{2}_{\text{before}}$ and the dichotomy that zero lift
forces exact orthogonality; and (vi) a \emph{blindness theorem}: by Dirichlet's theorem,
every attained dial value is shared by arbitrarily large primes and arbitrarily large
semiprimes, so no function of the dial carries any information about the factorization of
$N$.
\end{abstract}

\medskip
\noindent\textbf{Keywords.} Quadratic sieve; quadratic residues; sieve footprint; Chinese
remainder theorem; Hensel lifting; variance of arithmetic features; coefficient of
determination; information barrier.

\section{Introduction}

\subsection{The setting}
Let $N$ be a composite integer to be factored. The quadratic sieve evaluates
$v(x)=x^{2}-N$ at integers $x$ near $\sqrt N$ and retains those $x$ for which $v(x)$
factors completely over a \emph{factor base} of primes $p\le B$. Such $x$ yield
\emph{relations}, and enough relations produce a congruence of squares and a nontrivial
factor. Parameter choice --- the smoothness bound $B$, the sieve interval, the acceptance
threshold $u$ --- is governed by a \emph{yield model}: a predictor of the number of
relations per unit of sieving work for a given $N$.

\subsection{The feature and the observation}
For an odd prime $p$, the condition $p\mid x^{2}-N$ is $x^{2}\equiv N \pmod p$, which has
two solutions per period when $N$ is a nonzero quadratic residue mod $p$, one when
$p\mid N$, and none otherwise. Thus roughly half the factor base is inert for any given
$N$, and \emph{which} half is a function of $N$ modulo the base primes. This motivates the
\emph{footprint dial}
\[
  W(N)\;=\;\sum_{\substack{p\le B,\ p\ \text{odd prime}\\ N\ \text{a QR mod } p}}\frac{2}{p}.
\]
Empirically, adding $W$ to the baseline yield model raises out-of-sample $R^{2}$ from
$0.3927$ to $0.5691$ at acceptance parameter $u=2.5$ (a gain of $+0.176$, bootstrap
confidence interval $[0.120,0.229]$), and from $0.2063$ to $0.3078$ at $u=3.5$. A second,
independent feature --- the fraction of sieve values divisible by some prime $p\le 13$ ---
adds further, the pair reaching $R^{2}=0.5864$. The dial costs one Euler-criterion test
per odd factor-base prime ($77$ of them at $B=400$) plus one modular count.

\subsection{Contribution}
Every statement below is exact and finite: no asymptotics, no distributional assumptions,
no error terms. Sections~\ref{sec:mean}--\ref{sec:law} develop the arithmetic;
Section~\ref{sec:lift} the least-squares theory of a feature lift;
Section~\ref{sec:blind} the zero-information barrier; Section~\ref{sec:read} the empirical
reading; Sections~\ref{sec:apps}--\ref{sec:future} applications and open directions.

\section{Definitions}

Throughout $B\in\mathbb{N}$ is a smoothness bound and $N\in\mathbb{Z}$ a modulus.

\begin{definition}[Odd factor base]
The \emph{odd factor base} is $\base(B)=\{p\le B: p\ \text{prime},\ p\ne 2\}$, with
\emph{primorial} $D(B)=\prod_{p\in\base(B)}p$.
\end{definition}

\begin{definition}[Sieve hit count]
For a modulus $m\ge 1$,
$h(N,m)=\#\{x\in\{0,\dots,m-1\}: m\mid x^{2}-N\}$.
This is exactly what a sieve implementation counts when it initialises the roots of $m$.
\end{definition}

\begin{definition}[Quadratic residuacity, window form]
$N$ is a \emph{QR mod $p$}, written $\QR(N,p)$, if some $x\in\{0,\dots,p-1\}$ satisfies
$p\mid x^{2}-N$; equivalently the image of $N$ in $\mathbb{Z}/p$ is a square. The
convention includes the degenerate case $p\mid N$.
\end{definition}

\begin{definition}[Footprint weight and QR dial]
\[
  F(N,B)=\sum_{p\in\base(B)}\frac{h(N,p)}{p},
  \qquad
  W(N,B)=\sum_{\substack{p\in\base(B)\\ \QR(N,p)}}\frac{2}{p}.
\]
\end{definition}

\begin{definition}[Least-squares apparatus]
For a finite index set $I$ and $u,v:I\to\mathbb{R}$ write
$\langle u,v\rangle=\sum_i u_iv_i$, $\|u\|^{2}=\langle u,u\rangle$. For a target $y$, a
model class $S\subseteq\mathbb{R}^{I}$ and a single fit $g$,
\[
  \RSS(y,S)=\inf_{g\in S}\|y-g\|^{2},\quad
  \TSS(y)=\|y-\bar y\mathbf 1\|^{2},\quad
  R^{2}(y,S)=1-\frac{\RSS(y,S)}{\TSS(y)},\quad
  R^{2}(y,g)=1-\frac{\|y-g\|^{2}}{\TSS(y)} ,
\]
and the \emph{residual correlation}
$\rho(y,g,v)=\langle y-g,v\rangle/\sqrt{\|y-g\|^{2}\|v\|^{2}}$.
\end{definition}

\section{The dichotomy and the mean-footprint identity}\label{sec:mean}

\begin{lemma}[Transport]\label{lem:transport}
For any $p\ge 1$, $h(N,p)$ equals the number of $z\in\mathbb{Z}/p$ with $z^{2}=N$.
\end{lemma}

\begin{proof}[Proof sketch]
Reduction mod $p$ and choice of canonical representative are mutually inverse bijections
between $\{0,\dots,p-1\}$ and $\mathbb{Z}/p$, and $p\mid x^{2}-N$ holds iff the image of
$x^{2}-N$ vanishes.
\end{proof}

\begin{theorem}[The $2/1/0$ dichotomy]\label{thm:dich}
Let $p$ be an odd prime. If $p\nmid N$ and $\QR(N,p)$ then $h(N,p)=2$; if
$\neg\QR(N,p)$ then $h(N,p)=0$; if $p\mid N$ then $h(N,p)=1$. In all cases $h(N,p)\le 2$.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:transport} this counts square roots of $N$ in the field $\mathbb{Z}/p$.
A nonzero square in odd characteristic has exactly two roots $\pm z$, distinct because
$2\ne0$; a non-square has none; $0$ has one.
\end{proof}

\begin{lemma}[Periodicity]\label{lem:per}
$(x+p)^{2}-N=(x^{2}-N)+p(p+2x)$, so the predicate $p\mid x^{2}-N$ is $p$-periodic in $x$.
\end{lemma}

\begin{theorem}[Exact periodic counting]\label{thm:count}
If $P$ is a $p$-periodic predicate then $\#\{x<kp: P(x)\}=k\,\#\{x<p:P(x)\}$ for every $k$.
In particular $\#\{x<kp: p\mid x^{2}-N\}=k\,h(N,p)$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $k$, splitting off a translated final period and applying
Lemma~\ref{lem:per} $k$ times.
\end{proof}

\begin{theorem}[Mean-footprint identity]\label{thm:mfp}
Let $S$ be a finite set of positive moduli with product $M=\prod_{m\in S}m$. Then
\[
  \sum_{x=0}^{M-1}\#\{m\in S: m\mid x^{2}-N\}\;=\;M\sum_{m\in S}\frac{h(N,m)}{m}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Exchange summation: the left side counts pairs $(x,m)$ with $m\mid x^{2}-N$, hence equals
$\sum_{m\in S}\#\{x<M: m\mid x^{2}-N\}$. Since $m\mid M$, write $M=km$ and apply
Theorem~\ref{thm:count} to obtain $k\,h(N,m)=M\,h(N,m)/m$.
\end{proof}

\begin{corollary}[The feature is the mean footprint]\label{cor:feature}
If $N$ is coprime to every $p\in\base(B)$ then, with $D=D(B)$,
\[
  \frac1D\sum_{x=0}^{D-1}\#\{p\in\base(B): p\mid x^{2}-N\}\;=\;W(N,B),
\]
and in particular $F(N,B)=W(N,B)$.
\end{corollary}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:mfp} with $S=\base(B)$ and split according to residuacity: by
Theorem~\ref{thm:dich} the non-residue terms vanish and the residue terms equal $2/p$.
\end{proof}

The informal slogan ``each admissible prime divides about $2/p$ of the values'' is thus an
identity; the word ``about'' is unnecessary.

\section{Prime powers: Hensel lifting and the even prime}

\begin{theorem}[Hensel step]\label{thm:hensel}
Let $p$ be an odd prime with $p\nmid N$ and $k\ge1$. Then $h(N,p^{k+1})=h(N,p^{k})$, and
hence $h(N,p^{k})=h(N,p)$ for all $k\ge1$.
\end{theorem}

\begin{proof}[Proof sketch]
Reduction mod $p^{k}$ maps roots mod $p^{k+1}$ to roots mod $p^{k}$. Given a root $a$ mod
$p^{k}$, write $a^{2}-N=p^{k}m$ and seek a lift $a+tp^{k}$; the lifting condition is the
linear congruence $2at\equiv-m\pmod p$, solvable uniquely since $p$ is odd and $p\nmid a$.
Uniqueness of the lift follows since two lifts $x,y$ satisfy $p^{k+1}\mid(x-y)(x+y)$ with
$p\nmid x+y$. Hence reduction is a bijection.
\end{proof}

\begin{corollary}[Prime-power footprint density]\label{cor:ppdens}
For an odd prime $p$ with $p\nmid N$ and $k\ge1$,
\[
  \frac{h(N,p^{k})}{p^{k}}=
  \begin{cases}
    2/p^{k}, & \QR(N,p),\\
    0, & \text{otherwise.}
  \end{cases}
\]
\end{corollary}

\begin{theorem}[$\bmod\ 8$ obstruction]\label{thm:mod8}
If $N$ is odd and $N\not\equiv1\pmod 8$ then $h(N,2^{k})=0$ for every $k\ge3$.
\end{theorem}

\begin{proof}[Proof sketch]
$N$ odd forces any solution $x$ of $x^{2}\equiv N\pmod{2^{k}}$ to be odd, and every odd
square is $\equiv1\pmod 8$; hence $N\equiv1\pmod 8$, a contradiction.
\end{proof}

\section{The exact law of the dial}\label{sec:law}

Fix $B$ and let $P=D(B)$; every quantity below is $P$-periodic in $N$, so one full period
is the natural sample space.

\begin{theorem}[CRT counting]\label{thm:crt}
Let $(a_i)_{i\in I}$ be a finite pairwise-coprime family of positive moduli and $Q_i$ a
predicate on $\mathbb{Z}/a_i$. Then
\[
  \#\Bigl\{N<\prod_i a_i:\ Q_i(N\bmod a_i)\ \text{for all } i\Bigr\}
  \;=\;\prod_i \#\{z\in\mathbb{Z}/a_i: Q_i(z)\}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The Chinese remainder isomorphism $\mathbb{Z}/\prod a_i\cong\prod_i\mathbb{Z}/a_i$ is
compatible with reduction, so the left-hand set is in bijection with the product of the
local sets.
\end{proof}

\begin{lemma}[Local counts]\label{lem:local}
For an odd prime $p$, exactly $(p+1)/2$ of the $p$ residues mod $p$ are quadratic
residues: the $(p-1)/2$ nonzero squares together with $0$.
\end{lemma}

\begin{theorem}[Exact joint law]\label{thm:law}
For every $T\subseteq\base(B)$,
\[
  \#\{N<P:\ \{p\in\base(B):\QR(N,p)\}=T\}
  \;=\;\prod_{p\in T}\frac{p+1}{2}\cdot\prod_{p\in\base(B)\setminus T}\frac{p-1}{2},
\]
which is strictly positive. Hence every activation pattern occurs within one period, and
the indicators $\mathbf 1[\QR(N,p)]$ at distinct primes are exactly independent with
success probability $(p+1)/(2p)$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:crt} with $a_p=p$ and local predicate ``$z$ is a square iff
$p\in T$'', using Lemma~\ref{lem:local}. Positivity holds since $p\ge3$.
\end{proof}

\begin{theorem}[Means]\label{thm:means}
\[
  \frac1P\sum_{N=0}^{P-1}F(N,B)=\sum_{p\in\base(B)}\frac1p,
  \qquad
  \frac1P\sum_{N=0}^{P-1}W(N,B)=\sum_{p\in\base(B)}\frac{p+1}{p^{2}}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
For the first, exchange summation and use $\sum_{N\bmod p}h(N,p)=p$: each location $x$
contributes exactly once as $N$ runs over residues. For the second, the indicator has mean
$(p+1)/(2p)$ by Lemma~\ref{lem:local} and is weighted by $2/p$.
\end{proof}

The first sum is exactly the footprint of a \emph{random} integer. The dial is therefore
unbiased with respect to the random model: its mean carries no signal, and all predictive
content lives in the fluctuation. The excess $\sum 1/p^{2}$ in the second sum is the
contribution of the ramified residues $p\mid N$.

\begin{theorem}[Exact variance identity]\label{thm:var}
\[
  \frac1P\sum_{N=0}^{P-1}\Bigl(W(N,B)-\sum_{p\in\base(B)}\tfrac{p+1}{p^{2}}\Bigr)^{2}
  \;=\;\sum_{p\in\base(B)}\frac{p^{2}-1}{p^{4}}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Write $W=\sum_p(2/p)\mathbf 1_p$ and expand. Diagonal terms use
$\mathbf 1_p^{2}=\mathbf 1_p$ and Lemma~\ref{lem:local}, giving
$\frac{4}{p^{2}}\bigl(\frac{p+1}{2p}-\frac{(p+1)^{2}}{4p^{2}}\bigr)=\frac{p^{2}-1}{p^{4}}$;
off-diagonal terms vanish because, by Theorem~\ref{thm:law} applied to a pair, the
indicators are exactly uncorrelated.
\end{proof}

\begin{corollary}[Non-degeneracy]\label{cor:nondeg}
If $\base(B)\ne\emptyset$ the variance is strictly positive, so there are $N_1,N_2<P$ with
$W(N_1,B)\ne W(N_2,B)$: the dial is not a constant regressor.
\end{corollary}

\begin{theorem}[Uniform variance bound]\label{thm:varbound}
$\displaystyle\sum_{p\in\base(B)}\frac{p^{2}-1}{p^{4}}<\frac12$ for every $B$.
\end{theorem}

\begin{proof}[Proof sketch]
For $p\ge3$, $\frac{p^{2}-1}{p^{4}}\le\frac{1}{p^{2}}\le\frac{1}{p-1}-\frac1p$, and the
telescoping sum over odd primes is bounded by $1/2$.
\end{proof}

Thus the mean $\sum(p+1)/p^{2}$ diverges with $B$ while the variance converges and is
uniformly bounded: a bounded-fluctuation feature on a diverging trend.

\begin{theorem}[Injectivity of subset sums]\label{thm:inj}
If $T,S\subseteq\base(B)$ and $\sum_{p\in T}2/p=\sum_{p\in S}2/p$ then $T=S$.
\end{theorem}

\begin{proof}[Proof sketch]
Multiply by $D=D(B)$: the sum becomes the natural number
$\sigma(T)=\sum_{p\in T}2(D/p)$. For a base prime $p$, all terms with $q\ne p$ are
divisible by $p$, while $2(D/p)$ is not. Hence $p\mid\sigma(T)$ iff $p\notin T$.
\end{proof}

\begin{theorem}[Full dynamic range]\label{thm:range}
For every $T\subseteq\base(B)$ there is $N$ with $\{p:\QR(N,p)\}=T$, hence
$W(N,B)=\sum_{p\in T}2/p$.
\end{theorem}

\begin{proof}[Proof sketch]
Prescribe $N\equiv1\pmod p$ for $p\in T$ and $N\equiv c_p\pmod p$ for $p\notin T$ with
$c_p$ a non-residue (which exists, the squaring map on $(\mathbb{Z}/p)^{\times}$ being
two-to-one). Solve the system by an induction on the prime set using Bézout at each step,
then apply congruence invariance.
\end{proof}

\begin{theorem}[Exact capacity]\label{thm:cap}
The range of $N\mapsto W(N,B)$ is finite of cardinality exactly $2^{|\base(B)|}$, and
$W(N_1,B)=W(N_2,B)$ if and only if $N_1$ and $N_2$ have the same activation pattern.
\end{theorem}

\begin{proof}[Proof sketch]
The range lies in the set of subset sums (upper bound $2^{|\base(B)|}$);
Theorem~\ref{thm:range} shows every subset sum is attained; Theorem~\ref{thm:inj} shows
distinct subsets give distinct sums.
\end{proof}

So the dial carries exactly $|\base(B)|$ bits about $N$, no more and no fewer, however
large $N$ grows.

\section{What an $R^{2}$ lift measures}\label{sec:lift}

\begin{lemma}[Projection identity]\label{lem:proj}
For $r,v$ with $\|v\|^{2}\ne0$ and $t\in\mathbb{R}$,
$\|r-tv\|^{2}=\|r\|^{2}-2t\langle r,v\rangle+t^{2}\|v\|^{2}$, minimised at
$t^{\star}=\langle r,v\rangle/\|v\|^{2}$ with value
$\|r\|^{2}-\langle r,v\rangle^{2}/\|v\|^{2}$.
\end{lemma}

\begin{theorem}[RSS of a one-feature augmentation]\label{thm:rssline}
For a baseline $g$ and feature $v$ with $\|v\|^{2}\ne0$, the class
$\mathcal L=\{g+tv:t\in\mathbb{R}\}$ satisfies
$\RSS(y,\mathcal L)=\|y-g\|^{2}-\langle y-g,v\rangle^{2}/\|v\|^{2}$.
\end{theorem}

\begin{theorem}[Exact one-feature lift]\label{thm:lift}
If $\TSS(y)>0$ and $\|v\|^{2}\ne0$ then
\[
  R^{2}(y,\mathcal L)=R^{2}(y,g)+\frac{\langle y-g,v\rangle^{2}}{\|v\|^{2}\,\TSS(y)} .
\]
\end{theorem}

\begin{theorem}[The lift is a squared correlation]\label{thm:corr}
If moreover $\|y-g\|^{2}\ne0$ then
$\dfrac{\langle y-g,v\rangle^{2}}{\|v\|^{2}\TSS(y)}=\rho(y,g,v)^{2}\bigl(1-R^{2}(y,g)\bigr)$.
\end{theorem}

\begin{corollary}[Ceiling]\label{cor:ceiling}
$\Delta R^{2}\le 1-R^{2}(y,g)$ and $R^{2}(y,\mathcal L)\le1$.
\end{corollary}

\begin{proof}[Proof sketch]
Cauchy--Schwarz gives $\langle y-g,v\rangle^{2}\le\|y-g\|^{2}\|v\|^{2}$; equivalently
$\rho^{2}\le1$ in Theorem~\ref{thm:corr}.
\end{proof}

\begin{theorem}[Strictness and the null dichotomy]\label{thm:dichotomy}
If $\langle y-g,v\rangle\ne0$ then $R^{2}(y,g)<R^{2}(y,\mathcal L)$, and the same holds
for any model class containing $\mathcal L$. Conversely, if a class $T\supseteq\mathcal L$
satisfies $R^{2}(y,T)\le R^{2}(y,g)$, then $\langle y-g,v\rangle=0$ exactly.
\end{theorem}

The null hypothesis ``the residual contains nothing systematic aligned with $v$'' is
precisely $\langle y-g,v\rangle=0$, and by Theorem~\ref{thm:dichotomy} it is
\emph{equivalent} to observing exactly zero lift. A positive measured lift is therefore not
a fitting artefact but a certificate of nonzero residual--feature correlation, recoverable
by inverting Theorem~\ref{thm:corr}. Applied with $v_i=W(N_i,B)$ over a finite sample of
moduli (nondegenerate as soon as one sampled modulus has a nonzero dial), all of the above
holds verbatim for the footprint feature.

\section{The blindness barrier}\label{sec:blind}

\begin{lemma}[Residue invariance]\label{lem:resinv}
If $p\mid N_1-N_2$ then $\QR(N_1,p)\Leftrightarrow\QR(N_2,p)$. Hence if $N_1\equiv N_2$
modulo every $p\in\base(B)$ then $W(N_1,B)=W(N_2,B)$.
\end{lemma}

\begin{proof}[Proof sketch]
$x^{2}-N_2=(x^{2}-N_1)+(N_1-N_2)$, so divisibility by $p$ transfers; the index sets
defining $W$ then coincide.
\end{proof}

\begin{theorem}[Blind to primality and semiprimality]\label{thm:blindparts}
Let $N$ be coprime to $D(B)$ and let $n$ be arbitrary. Then there is a prime $q>n$ with
$W(q,B)=W(N,B)$, and there are distinct primes $r,s$ with $rs>n$ and $W(rs,B)=W(N,B)$.
\end{theorem}

\begin{proof}[Proof sketch]
By Dirichlet the class $N+D(B)\mathbb{Z}$ contains arbitrarily large primes. For the
semiprime, take a large prime $r\equiv1\pmod{D(B)}$ and then a large prime
$s\equiv Nr^{-1}\pmod{D(B)}$; then $rs\equiv N$ modulo every base prime. Conclude with
Lemma~\ref{lem:resinv}.
\end{proof}

\begin{theorem}[Blindness theorem]\label{thm:blind}
Fix $B$, a modulus $N$ coprime to $D(B)$, an arbitrary function $c$ from dial values to
$\{\text{true},\text{false}\}$, and any bound $n$. Then there exist a prime $q>n$ and
distinct primes $r,s$ with $rs>n$ such that
\[
  c\bigl(W(q,B)\bigr)=c\bigl(W(N,B)\bigr)=c\bigl(W(rs,B)\bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Immediate from Theorem~\ref{thm:blindparts}: the classifier receives identical input in all
three cases.
\end{proof}

The conclusion is unconditional and assumes nothing about $c$ --- no measurability, no
computability, no efficiency. Every dial value is shared by arbitrarily large primes and by
arbitrarily large semiprimes, so no decision rule based on the dial can separate them, let
alone reveal a factor.

